// n8n Code node: "Find stale applications" (workflows/weekly-digest.json)
// Generated by scripts/export-code.js. Edit the workflow, not this file.

// Applications still at 'Applied' with no reply after N days → mark No Response.
const days = Number($('Config').first().json.noResponseAfterDays) || 21;
const cutoff = Date.now() - days * 86400000;
const out = [];
for (const pg of ($input.first().json.results || [])) {
  const p = pg.properties || {};
  const status = p['Status']?.select?.name || '';
  const applied = p['Applied Date']?.date?.start;
  const lastReply = p['Last Reply Date']?.date?.start;
  if (status === 'Applied' && applied && !lastReply && new Date(applied).getTime() < cutoff) {
    out.push({ json: { pageId: pg.id } });
  }
}
return out;
